local _, ns = ...
local Translate = ns.Lore.Translate

Translate("frFR", "thunder-bluff", {
	title = "Thunder Bluff",
	aliases = { "la cité de Thunder Bluff" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thunder Bluff est la capitale des {link:tauren}taurens{/link}, élevée sur un groupe de mesas battues par les vents qui dominent de plusieurs centaines de pieds les plaines de {link:mulgore}Mulgore{/link}. Des ponts de bois et de corde se balancent entre les hauteurs, et chaque mesa est couronnée de tentes, de longues maisons, de totems peints et de huttes des esprits. De grandes élévations de corde et de bois portent les voyageurs depuis l'herbe en contrebas, et des coursiers du vent tournoient autour de la tour centrale. C'est une cité de nombreuses tribus et un refuge pour les chasseurs, les marchands et les artisans de tout genre. Depuis sa hutte sur la mesa centrale, le grand chef {link:cairne-bloodhoof}Cairne Bloodhoof{/link} veille sur eux tous.]=],
		},
		{
			title = "Origines",
			text = [=[Pendant d'innombrables générations, les taurens n'eurent pas de cité. Ils étaient nomades, et les {link:centaurs}centaures{/link} les pourchassaient à travers les plaines, si bien que leurs tribus devinrent peu nombreuses et dispersées. {link:cairne-bloodhoof}Cairne{/link} des Bloodhoof rêvait d'une terre où son peuple pourrait vivre en paix. Avec l'aide de {link:thrall}Thrall{/link} et des orcs de la {link:horde}Horde{/link}, les taurens chassèrent les centaures de {link:mulgore}Mulgore{/link}. Sur les mesas de son extrémité nord, Cairne bâtit un refuge où les taurens de toutes les tribus seraient les bienvenus. Aucune chronique ne rapporte l'année de son achèvement. Avec le temps, les tribus dispersées y vinrent et s'unirent sous son autorité.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[{link:cairne-bloodhoof}Cairne{/link} est vieux, mais sa force et sa sagesse maintiennent encore les tribus unies. Toutes les tribus n'approuvent pas la voie qu'il a choisie. Sur la {link:elder-rise}Cime des Anciens{/link}, {link:magatha-grimtotem}Magatha Grimtotem{/link}, la doyenne des Totem sinistre, tient son propre conseil et garde ses propres gardes, et elle croit que c'est elle, et non Cairne, qui devrait mener les taurens. À ses côtés, les druides du {link:cenarion-circle}Cercle cénarien{/link} entretiennent leurs huttes sous la conduite de l'archidruide {link:hamuul-runetotem}Hamuul Runetotem{/link}. Des émissaires des {link:forsaken}Réprouvés{/link} demeurent dans les {link:the-pools-of-vision}Bassins de la Vision{/link} et enseignent sur la {link:spirit-rise}Cime des Esprits{/link}, signe du pacte qui les fit entrer dans la {link:horde}Horde{/link}. Les sages de la cité sont connus dans toute la Horde comme historiens. En ces jours, de nouveaux visages sont aussi apparus : des prêtres d'An'she, le soleil, et des elfes {link:skyborne}Skyborne{/link} qui passent en chemin du camp du {link:earthen-ring}Cercle terrestre{/link} vers {link:orgrimmar}Orgrimmar{/link}.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les taurens de nombreuses tribus.{/b} Les Bloodhoof, les Runetotem, les Wildmane, les Thunderhorn, les Ragetotem, les Stonehoof, les Mistrunner et bien d'autres exercent leurs métiers sur les cimes.
• {b}Les Totem sinistre.{/b} {link:magatha-grimtotem}Magatha{/link} et ses serviteurs tiennent un coin de la {link:elder-rise}Cime des Anciens{/link}.
• {b}Les druides.{/b} Des taurens du {link:cenarion-circle}Cercle cénarien{/link}, menés par {link:hamuul-runetotem}Hamuul Runetotem{/link}.
• {b}Les {link:forsaken}Réprouvés{/link}.{/b} Des apothicaires, des prêtres et des mages envoyés d'{link:undercity}Undercity{/link}.
• {b}Les voyageurs de la {link:horde}Horde{/link}.{/b} {link:orcs}Orcs{/link}, trolls et désormais {link:skyborne}Skyborne{/link} vont et viennent par coursier du vent et par élévation.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La Longue Marche.{/b} Les orcs de {link:thrall}Thrall{/link} escortèrent le peuple de {link:cairne-bloodhoof}Cairne{/link} à travers les {link:the-barrens}Tarides{/link} jusqu'en {link:mulgore}Mulgore{/link}, et Cairne engagea les taurens aux côtés de la {link:horde}Horde{/link}.
• {b}La {link:third-war}Troisième Guerre{/link}.{/b} Des guerriers taurens combattirent aux côtés des orcs, des humains et des elfes de la nuit à la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}.
• {b}La fondation.{/b} Une fois les centaures repoussés, Cairne éleva Thunder Bluff et y appela les tribus.
• {b}Le pacte avec les {link:forsaken}Réprouvés{/link}.{/b} Quand les Réprouvés cherchèrent une place dans la Horde, les anciens du {link:earthen-ring}Cercle terrestre{/link} pressèrent qu'on les aide. Cairne accepta, et les Réprouvés vinrent à Thunder Bluff en alliés.]=],
		},
		{
			title = "Savoir des Pitons",
			text = [=[• Les taurens ont coutume de disperser de l'encens aux vents depuis la falaise sud de la {link:hunter-rise}Cime des chasseurs{/link}.
• Un jeune {link:tauren}tauren{/link} qui se présente devant le grand chef porte une coiffe, et les plus belles sont faites de plumes de harpies du nord.
• Les sages de Thunder Bluff ont étudié des disques de métal rapportés d'{link:uldaman}Uldaman{/link}, dont les glyphes parlent d'un lieu perdu appelé {link:valley-of-the-watchers}Uldum{/link}.]=],
		},
	},
})

Translate("frFR", "elder-rise", {
	title = "Cime des Anciens",
	sections = {
		{
			title = "Résumé",
			text = [=[La Cime des Anciens est le piton nord-est de {link:thunder-bluff}Thunder Bluff{/link}, la demeure des sages de la cité. Les druides du {link:cenarion-circle}Cercle cénarien{/link} y entretiennent leurs huttes sous la conduite de l'archidruide {link:hamuul-runetotem}Hamuul Runetotem{/link}, avec à ses côtés sa fille Bashana, la jeune druidesse {link:nara-wildmane}Nara Wildmane{/link} et les maîtres des arts druidiques. Dans une hutte à elle, gardée par deux guerriers de son clan, vit {link:magatha-grimtotem}Magatha Grimtotem{/link}, la doyenne. Les deux anciens partagent la même cime et rarement le même avis. Ceux qui cherchent conseil sur les maux du pays, qu'il s'agisse d'esprits, de rêves ou de la terre elle-même, sont envoyés ici.]=],
		},
	},
})

Translate("frFR", "spirit-rise", {
	title = "Cime des Esprits",
	sections = {
		{
			title = "Résumé",
			text = [=[La Cime des Esprits est le piton ouest de {link:thunder-bluff}Thunder Bluff{/link}, où les chamans de la famille Skychaser apprennent aux jeunes à parler avec les esprits des {link:elements}éléments{/link}. C'est aussi la cime des étrangers. Des prêtres et des mages des {link:forsaken}Réprouvés{/link} y enseignent désormais, et un sentier caché descend en serpentant de la cime jusqu'à la grotte des {link:the-pools-of-vision}Bassins de la Vision{/link}, où les apothicaires d'{link:undercity}Undercity{/link} mènent leurs travaux. En ces jours, un maître des paladins est lui aussi venu sur la cime. Pour beaucoup de taurens, la Cime des Esprits est l'endroit où ils rencontrent pour la première fois les morts qui sont aujourd'hui leurs alliés.]=],
		},
	},
})

Translate("frFR", "hunter-rise", {
	title = "Cime des chasseurs",
	aliases = { "Cime des chasseurs" },
	sections = {
		{
			title = "Résumé",
			text = [=[La Cime des chasseurs est le piton sud de {link:thunder-bluff}Thunder Bluff{/link}, la cime de ceux qui vivent de la chasse et de la lance. Les chasseurs de la famille Thunderhorn apprennent aux jeunes à pister et à dresser, et les guerriers Ragetotem leur apprennent à combattre. Le grand chasseur {link:melor-stonehoof}Melor Stonehoof{/link} organise d'ici ses chasses les plus dures, contre des bêtes qui vivent hors de la bénédiction de la Terre-mère. Depuis la falaise sud de la cime, les taurens dispersent de l'encens aux vents, comme le veut leur tradition, et contemplent tout {link:mulgore}Mulgore{/link}.]=],
		},
	},
})

Translate("frFR", "the-pools-of-vision", {
	title = "Les Bassins de la Vision",
	aliases = { "Bassins de la Vision" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Bassins de la Vision se trouvent dans une grotte sous la {link:spirit-rise}Cime des Esprits{/link}, que l'on atteint par un sentier caché. Une eau immobile emplit la caverne, et les taurens la tiennent pour sacrée. En ces jours, les bassins sont devenus la demeure des émissaires {link:forsaken}réprouvés{/link} à {link:thunder-bluff}Thunder Bluff{/link}. L'apothicaire {link:apothecary-zamah}Zamah{/link} de la {link:royal-apothecary-society}Société royale des apothicaires{/link} y travaille, recevant d'étranges envois et en expédiant d'autres. C'est vers elle que se tourna {link:magatha-grimtotem}Magatha Grimtotem{/link} quand elle chercha un remède au mal des {link:stonetalon-mountains}Serres-Rocheuses{/link}, et le remède qu'offrirent les Réprouvés était un poison.]=],
		},
	},
})

Translate("frFR", "cairne-bloodhoof", {
	title = "Cairne Bloodhoof",
	subtitle = "Grand chef des taurens",
	found = "Sa hutte sur la mesa centrale de Thunder Bluff",
	hint = [=[Montez jusqu'à la plus haute mesa de Thunder Bluff et demandez audience au grand chef.]=],
	allegiance = "Taurens · Tribu Bloodhoof · Horde",
	aliases = { "Cairne", "grand chef Cairne Bloodhoof" },
	sections = {
		{
			title = "Résumé",
			text = [=[Cairne Bloodhoof est le grand chef des taurens et le fondateur de {link:thunder-bluff}Thunder Bluff{/link}. Il fut jadis le chef d'une seule tribu, les Bloodhoof, qui erraient dans les plaines près de la Grande mer et vivaient dans la crainte des centaures. Il est aujourd'hui le seigneur de toutes les tribus taurens et l'un des grands piliers de la {link:horde}Horde{/link}. L'âge l'a ralenti, mais ne l'a pas courbé. C'est un guerrier sans égal, un juge patient et un ami de ceux qui honorent la terre.]=],
		},
		{
			title = "Importance",
			text = [=[Cairne donna un foyer à son peuple. C'est son alliance avec {link:thrall}Thrall{/link} qui sauva les taurens des centaures, et sa parole qui les lia à la {link:horde}Horde{/link}. Par lui, la Horde gagna plus que des guerriers : elle gagna un peuple d'une profonde sagesse et d'une foi ancienne. En ces jours, le grand chef maintient encore les tribus unies, même si toutes n'approuvent pas la direction qu'il leur donne.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il rencontra {link:thrall}Thrall{/link} dans les plaines de {link:kalimdor}Kalimdor{/link} et lui montra le chemin de l'Oracle du {link:stonetalon-peak}Pic des Serres-Rocheuses{/link}.
• Il mena son peuple à travers les {link:the-barrens}Tarides{/link} jusqu'en {link:mulgore}Mulgore{/link} sous la protection des orcs.
• Il engagea les taurens dans la {link:horde}Horde{/link} et combattit à la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}.
• Il fonda {link:thunder-bluff}Thunder Bluff{/link} et fit de Mulgore un foyer pour toutes les tribus.
• Il accueillit les {link:forsaken}Réprouvés{/link} dans la Horde.
• Il entretient ses propres éclaireurs, les {link:longwalkers}Longwalkers{/link}, et leur confie ses secrets.]=],
		},
		{
			title = "Non consigné",
			text = [=[Les chroniques de cet âge disent peu de chose de la jeunesse de Cairne, ou des années qui précédèrent le moment où les centaures menèrent sa tribu au bord de la ruine.]=],
		},
	},
	chapters = {
		{
			title = "La Longue Marche",
			hint = [=[Accomplissez les Rites de la Terre-mère et présentez-vous devant le grand chef.]=],
			text = [=[Avant que les taurens aient un foyer, les centaures pourchassaient le peuple de Cairne d'un camp à l'autre. Quand le jeune chef de guerre {link:thrall}Thrall{/link} les trouva en plein combat, Cairne vit dans les orcs un peuple aussi sauvage que noble. Il parla à Thrall de l'Oracle du nord. Thrall, en retour, jura de protéger les caravanes taurens à travers les {link:the-barrens}Tarides{/link}, et les orcs repoussèrent vague après vague de centaures jusqu'à ce que les taurens atteignent {link:mulgore}Mulgore{/link}. Cairne n'oublia pas cette dette. Il suivit Thrall aux {link:stonetalon-mountains}Serres-Rocheuses{/link}, et depuis ce jour les taurens marchent avec la {link:horde}Horde{/link}.]=],
		},
		{
			title = "La corne d'Arra'chea",
			hint = [=[Prouvez votre valeur au grand chef par une chasse dans les plaines en contrebas.]=],
			text = [=[Pour Cairne, une place à {link:thunder-bluff}Thunder Bluff{/link} ne se gagne pas une fois pour toutes. Elle doit être conservée. Il rappelle à chaque jeune {link:tauren}tauren{/link} qui atteint sa hutte que leur peuple est un peuple de chasseurs, et il l'envoie dans les plaines pister et tuer le grand kodo Arra'chea. Quand la corne est rapportée, il envoie un groupe recueillir la peau et la viande, afin que rien de la bête ne soit gaspillé.]=],
		},
		{
			title = "Les Longwalkers",
			hint = [=[Apportez au grand chef des nouvelles de son éclaireur disparu.]=],
			text = [=[Cairne envoya le {link:longwalkers}Longwalker{/link} {link:perith-stormhoof}Perith Stormhoof{/link} parlementer avec les {link:palemane-gnolls}gnolls Crins-pâles{/link}, et les gnolls le firent prisonnier. Quand vint la nouvelle que Perith était sain et sauf, Cairne fut soulagé. Il désigna Perith comme son éclaireur le plus digne de confiance et sa mission comme de la plus haute importance, et il n'en dit pas davantage sur la nature de cette mission.]=],
		},
		{
			title = "Le retour des Galak",
			hint = [=[Chassez les centaures de Mulgore et faites votre rapport au grand chef.]=],
			text = [=[La nouvelle que les Galak avaient osé piller {link:mulgore}Mulgore{/link} raviva la colère du vieux guerrier. Il avait chassé les centaures de ces plaines aux côtés de {link:thrall}Thrall{/link}, et il honora ceux qui les chassèrent à nouveau, afin que les centaures se souviennent de la douleur qui les attend s'ils reviennent.]=],
		},
	},
	mentions = {
		{ text = "Voyage vers {link:thunder-bluff}Thunder Bluff{/link}" },
		{
			text = [=[À la découverte de la {link:horde}Horde{/link}, une invitée skyborne dans sa hutte]=],
		},
		{
			text = [=[{link:rites-of-the-earthmother}Rites de la Terre-mère{/link}, le dernier des rites]=],
		},
	},
	bonds = {
		{ id = "baine-bloodhoof", name = "Baine Bloodhoof", note = "son fils" },
		{ id = "thrall", name = "Thrall", note = "son ami et chef de guerre" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "un ami d'enfance" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "sa rivale parmi les anciens" },
		{ id = "perith-stormhoof", name = "Perith Stormhoof", note = "son éclaireur le plus fidèle" },
		{ id = "muln-earthfury", name = "Muln Earthfury", note = "ancien du Cercle terrestre" },
	},
})

Translate("frFR", "magatha-grimtotem", {
	title = "Magatha Grimtotem",
	subtitle = "Doyenne des Totem sinistre",
	found = "Sa hutte sur la Cime des Anciens",
	hint = [=[Demandez conseil à la doyenne qui demeure sur la Cime des Anciens.]=],
	allegiance = "Clan Totem sinistre · Thunder Bluff",
	aliases = { "Magatha", "la doyenne" },
	sections = {
		{
			title = "Résumé",
			text = [=[Magatha Grimtotem est la doyenne des Totem sinistre, une chamane que beaucoup tiennent pour la plus puissante des taurens, et l'une des plus âgées de leurs anciens. Elle demeure dans une hutte sur la {link:elder-rise}Cime des Anciens{/link}, servie par deux guerriers de son clan et par son serviteur Rahauro. Beaucoup viennent lui demander conseil, et elle le donne volontiers. Ce qu'elle veut en retour, peu sauraient le dire.]=],
		},
		{
			title = "Importance",
			text = [=[Magatha est la grande rivale de {link:cairne-bloodhoof}Cairne Bloodhoof{/link}. Elle a recherché le pouvoir et le rang presque toute sa vie, et elle croit qu'elle seule est digne de mener les taurens. Les guerriers de son clan la suivent, et ils rêvent de chasser les races inférieures de {link:kalimdor}Kalimdor{/link}. Pourtant, elle vit dans la cité du grand chef, siège parmi ses anciens et parle pour les {link:forsaken}Réprouvés{/link}, qu'elle a aidés plus qu'aucun autre {link:tauren}tauren{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle reçut les dons d'une chamane alors qu'elle n'était encore qu'une fillette.
• Elle devint matriarche des Totem sinistre par un mariage arrangé. Beaucoup soupçonnent qu'elle l'arrangea elle-même. Son compagnon mourut peu après dans un accident d'escalade que nul n'avait prévu.
• Elle plaida pour les {link:forsaken}Réprouvés{/link} quand leur pacte avec la {link:horde}Horde{/link} fut proposé pour la première fois.
• Elle cherche un moyen, dit-elle, pour que les Réprouvés retrouvent le chemin de la vie.
• Elle envoya des émissaires traiter avec les troggs du {link:ragefire-chasm}Gouffre de Ragefeu{/link} sous {link:orgrimmar}Orgrimmar{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le mal qui ronge la terre",
			hint = "Exposez à la doyenne le malheur des Serres-Rocheuses.",
			text = [=[Quand lui parvinrent des nouvelles des esprits troublés des {link:stonetalon-mountains}Serres-Rocheuses{/link}, Magatha dit que la terre ne pourrait être guérie tant que le mal qui la rongeait ne serait pas ôté. Ce mal était la {link:venture-company}KapitalRisk{/link}. Elle se tourna vers les {link:forsaken}Réprouvés{/link}, disant que leur savoir des maladies renforcerait la confiance entre les deux peuples. Les apothicaires répondirent par une toxine, destinée à se répandre parmi les gobelins comme une peste.]=],
		},
		{
			title = "La tablette de Beth'Amara",
			hint = "Portez une tablette ancienne à la doyenne.",
			text = [=[De la lointaine {link:azshara}Azshara{/link} vint une tablette, envoyée par un agent nommé {link:jediga}Jediga{/link}, qui avait reçu l'ordre de la remettre en mains propres à Magatha. Magatha affirma qu'elle pourrait lui montrer comment les taurens pourraient aider les {link:forsaken}Réprouvés{/link} à redevenir humains. Elle fut satisfaite du travail, et elle promit son paiement à Jediga.]=],
		},
		{
			title = "Le serpent de vengeance",
			hint = "Répondez à l'avertissement de la doyenne au sujet d'Arikara.",
			text = [=[Magatha enchanta une poudre qui invoquerait {link:arikara}Arikara{/link}, un serpent de vengeance, hors du feu sacré de la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link} à {link:thousand-needles}Mille pointes{/link}. Elle avertit que le serpent traquait peut-être {link:cairne-bloodhoof}Cairne Bloodhoof{/link}, irrité parce que trop du savoir {link:tauren}tauren{/link} avait changé. Les taurens du {link:freewind-post}Poste de Librevent{/link} ne comprenaient pas pourquoi Arikara chasserait le grand chef. Ils ne doutaient pas de Magatha. Elle était, disaient-ils, leur chamane la plus puissante.]=],
		},
		{
			title = "Les troggs de Ragefeu",
			hint = "Récupérez la sacoche de l'émissaire perdu de Magatha.",
			text = [=[Magatha cherchait la paix avec les troggs remontés des profondeurs sous {link:orgrimmar}Orgrimmar{/link}. Ils tuèrent ses diplomates à la place. L'un de ses serviteurs, {link:maur-raincaller}Maur{/link} Grimtotem, mourut dans le {link:ragefire-chasm}Gouffre de Ragefeu{/link} en serrant une sacoche. Magatha voulait la récupérer, et elle déclara les troggs une menace pour toute la {link:horde}Horde{/link}.]=],
		},
	},
	mentions = {
		{ text = "La doyenne" },
		{ text = "Le paiement de Magatha à {link:jediga}Jediga{/link}" },
		{ text = "Feu sacré" },
		{
			text = [=[Tester la force d'un ennemi, envoyé par son serviteur Rahauro]=],
		},
		{ text = "À la recherche de la sacoche perdue" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "son rival" },
		{ id = "apothecary-zamah", name = "Apothicaire Zamah", note = "la Réprouvée en qui elle a confiance" },
		{ id = "sage-truthseeker", name = "Sage Truthseeker", note = "se méfie du pacte qu'elle a défendu" },
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "partage la Cime des Anciens" },
	},
})

Translate("frFR", "hamuul-runetotem", {
	title = "Hamuul Runetotem",
	subtitle = "Archidruide de Thunder Bluff",
	found = "Sa hutte sur la Cime des Anciens",
	hint = [=[Cherchez le vieux druide qui a sa hutte sur la Cime des Anciens.]=],
	allegiance = "Cercle cénarien · Taurens",
	aliases = { "Archidruide Hamuul Runetotem", "Hamuul", "Archidruide Runetotem" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'archidruide Hamuul Runetotem est le premier druide {link:tauren}tauren{/link} depuis de nombreuses générations et le chef des druides de {link:thunder-bluff}Thunder Bluff{/link}. Il fut ému par les druides qui combattirent au mont Hyjal, et après la guerre il alla trouver {link:malfurion-stormrage}Malfurion Stormrage{/link} et demanda à être instruit. Il est membre du {link:cenarion-circle}Cercle cénarien{/link} et un ami de {link:cairne-bloodhoof}Cairne{/link} depuis l'enfance.]=],
		},
		{
			title = "Importance",
			text = [=[Hamuul ouvrit aux taurens les anciennes voies des elfes de la nuit. Grâce à lui, les druides des deux peuples travaillent désormais côte à côte, et sa hutte sur la {link:elder-rise}Cime des Anciens{/link} est l'endroit vers lequel se tournent les taurens quand la terre elle-même tombe malade.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie les jeunes aider les druides qui cherchent une étrange puissance qui s'infiltre dans les {link:the-barrens}Tarides{/link}.
• Il pénétra dans le rêve pour apprendre ce qui empoisonne les Tarides.
• Il conseille aux jeunes druides de regarder au-delà des querelles entre peuples dans leurs rapports avec le Cercle.
• Il étudie le sol d'{link:un-goro-crater}Un'Goro{/link} et la croissance du grain d'aurore.]=],
		},
	},
	chapters = {
		{
			title = "Les Druides du Croc",
			hint = [=[Apportez à l'archidruide les carapaces souillées des Tarides.]=],
			text = [=[La souillure des oasis des {link:the-barrens}Tarides{/link} menait aux {link:wailing-caverns}Cavernes des lamentations{/link}. Hamuul entra dans le pays des rêves et y vit une secte de druides, jadis nobles, qui s'étaient égarés et servaient désormais la souillure. Il était vieux, et il ne put rester longtemps dans le rêve. La jeune {link:nara-wildmane}Nara Wildmane{/link} y resta quand il s'enfuit.]=],
		},
		{
			title = "Un éclat de cauchemar",
			hint = "Remettez un étrange éclat à l'archidruide.",
			text = [=[Un éclat du {link:emerald-dream}Rêve d'émeraude{/link} lui parvint d'un druide qui refusait d'en parler. Hamuul le contempla, se tut, et dit seulement que les choses dans le Rêve n'étaient pas telles que les druides l'avaient cru. Il conseilla de ne pas parler de telles choses.]=],
		},
		{
			title = "Les puits purifiés",
			hint = [=[Portez à Thunder Bluff la nouvelle des puits purifiés de Mulgore.]=],
			text = [=[Quand {link:mull-thunderhorn}Mull Thunderhorn{/link} rapporta que les trois {link:water-wells-of-mulgore}puits de Mulgore{/link} avaient été purifiés, Hamuul dit que la joie coulait de nouveau dans les ruisseaux, car les puits servent les bêtes autant que les gens.]=],
		},
	},
	mentions = {
		{ text = "Les oasis des {link:the-barrens}Tarides{/link}" },
		{ text = "{link:nara-wildmane}Nara Wildmane{/link}" },
		{ text = "{link:rabine-saturna}Rabine Saturna{/link}" },
		{ text = "Terre d'{link:un-goro-crater}Un'Goro{/link}" },
		{ text = "Recherches sur le grain d'aurore" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "un ami d'enfance" },
		{ id = "nara-wildmane", name = "Nara Wildmane", note = "une jeune druidesse à l'esprit farouche" },
		{ id = "mull-thunderhorn", name = "Mull Thunderhorn", note = "lui annonça la nouvelle des puits" },
		{ id = "malfurion-stormrage", name = "Malfurion Stormrage", note = "son maître" },
	},
})

Translate("frFR", "sage-truthseeker", {
	title = "Sage Truthseeker",
	subtitle = "Sage de Thunder Bluff",
	found = "La cime inférieure de Thunder Bluff",
	hint = [=[Cherchez le sage qui rassemble pour les taurens le savoir perdu d'Azeroth.]=],
	allegiance = "Thunder Bluff · Les sages",
	aliases = { "Truthseeker" },
	sections = {
		{
			title = "Résumé",
			text = [=[Sage Truthseeker est l'un des sages de {link:thunder-bluff}Thunder Bluff{/link}, les historiens des taurens. Il rassemble de vieux livres, des reliques et des secrets venus de tout le monde et les étudie pour son peuple. Il confierait sa vie à {link:cairne-bloodhoof}Cairne{/link}. Il ne se fie pas aux {link:forsaken}Réprouvés{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Le sage parle pour les taurens qui doutent du pacte avec les morts. Il croit que le {link:earthen-ring}Cercle terrestre{/link} était bien intentionné quand il pressa la {link:horde}Horde{/link} de les aider, mais il se demande qui murmurait à l'oreille de son Conseil des anciens. Il se tient aussi au seuil d'un mystère plus profond, qui remonte aux créateurs du monde.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il chercha le Compendium des Déchus auprès des fanatiques du {link:scarlet-monastery}Monastère écarlate{/link}.
• Il étudie les disques de Norgannon rapportés d'{link:uldaman}Uldaman{/link}.
• Lui et {link:nara-wildmane}Nara Wildmane{/link} suivent la piste des disques vers {link:valley-of-the-watchers}Uldum{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le Compendium des Déchus",
			hint = [=[Apportez au sage le livre que gardent les fanatiques écarlates.]=],
			text = [=[Les {link:forsaken}Réprouvés{/link} ont une histoire pleine de tromperies, dit le sage, et le pacte fut conclu trop vite. Peut-être {link:cairne-bloodhoof}Cairne{/link} aurait-il dû écouter les avertissements venus d'{link:orgrimmar}Orgrimmar{/link}. Les fanatiques de la {link:scarlet-crusade}Croisade écarlate{/link} sont fous, mais ils ont étudié les morts-vivants, et Truthseeker voulait savoir ce qu'ils avaient appris. Il avait commencé à se demander si leur livre existait seulement.]=],
		},
		{
			title = "Les disques de platine",
			hint = "Apportez au sage une relique des chambres fortes d'Uldaman.",
			text = [=[D'{link:uldaman}Uldaman{/link} vint une copie miniature des disques de platine de Norgannon. Le sage y sentit des secrets que la terre avait gardés serrés pendant des âges. Il s'appliqua à comprendre leur fonctionnement, et promit qu'ils se révéleraient en temps voulu.]=],
		},
		{
			title = "Présages d'Uldum",
			hint = "Suivez les glyphes traduits des disques.",
			text = [=[Les glyphes des disques parlaient d'un lieu appelé {link:valley-of-the-watchers}Uldum{/link}, que la plupart croient être un mythe. Truthseeker porta l'affaire à {link:nara-wildmane}Nara Wildmane{/link}, qui avait vu les portes scellées de {link:stranglethorn-vale}la Vallée{/link} des guetteurs en {link:tanaris}Tanaris{/link}. Ensemble, ils conclurent que les disques et Uldum étaient liés.]=],
		},
	},
	mentions = {
		{ text = "Les disques de platine" },
		{ text = "Voir ce qui se passe" },
		{ text = "Une tâche à venir" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "à qui il confierait sa vie" },
		{ id = "nara-wildmane", name = "Nara Wildmane", note = "partage son étude d'Uldum" },
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "championne du pacte dont il se méfie" },
	},
})

Translate("frFR", "nara-wildmane", {
	title = "Nara Wildmane",
	subtitle = "Druidesse de la Cime des Anciens",
	found = "Une tente sur la Cime des Anciens",
	hint = [=[Trouvez la jeune druidesse qui resta dans le rêve quand d'autres s'enfuirent.]=],
	allegiance = "Cercle cénarien · Taurens",
	aliases = { "Nara" },
	sections = {
		{
			title = "Résumé",
			text = [=[Nara Wildmane est une jeune druidesse de la {link:elder-rise}Cime des Anciens{/link}. {link:hamuul-runetotem}Hamuul Runetotem{/link} dit de son esprit qu'il est farouche. Quand l'archidruide ne put plus supporter le rêve des {link:wailing-caverns}Cavernes des lamentations{/link}, Nara y resta et apprit les visages des quatre chefs des {link:druids-of-the-fang}Druides du Croc{/link}. Elle a voyagé loin, et s'est tenue devant {link:valley-of-the-watchers}les portes scellées d'Uldum{/link} dans le sud.]=],
		},
		{
			title = "Importance",
			text = [=[Nara est la génération suivante des druides taurens. Là où la force de {link:hamuul-runetotem}Hamuul{/link} faiblit, la sienne prend le relais.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle cherche les gemmes de rêve des quatre chefs des {link:druids-of-the-fang}Druides du Croc{/link}.
• Elle aide {link:sage-truthseeker}Sage Truthseeker{/link} dans son étude des disques.]=],
		},
	},
	mentions = {
		{ text = "Nara Wildmane" },
		{ text = "Les chefs du Croc" },
		{ text = "Présages d'{link:valley-of-the-watchers}Uldum{/link}" },
		{ text = "Voir ce qui se passe" },
	},
	bonds = {
		{ id = "hamuul-runetotem", name = "Hamuul Runetotem", note = "son aîné" },
		{ id = "sage-truthseeker", name = "Sage Truthseeker", note = "partage son étude d'Uldum" },
	},
})

Translate("frFR", "apothecary-zamah", {
	title = "Apothicaire Zamah",
	subtitle = "Émissaire des Réprouvés",
	found = "Les Bassins de la Vision",
	hint = [=[Trouvez l'apothicaire réprouvée qui travaille dans la grotte sous la Cime des Esprits.]=],
	allegiance = "Société royale des apothicaires · Réprouvés",
	aliases = { "Zamah" },
	sections = {
		{
			title = "Résumé",
			text = [=[L'apothicaire Zamah est une érudite de la {link:royal-apothecary-society}Société royale des apothicaires{/link} et une émissaire des {link:forsaken}Réprouvés{/link} auprès des taurens. Elle travaille dans les {link:the-pools-of-vision}Bassins de la Vision{/link}, sous la {link:spirit-rise}Cime des Esprits{/link}. Elle dit servir {link:sylvanas-windrunner}la Dame noire{/link} et l'avancement de son peuple, et elle étudie avec grand intérêt les herbes et les spores de {link:kalimdor}Kalimdor{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Zamah est le visage du pacte entre les taurens et les morts. {link:magatha-grimtotem}Magatha{/link} lui fait confiance. Beaucoup d'autres non.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Elle cherche des fleurs de serpent dans les profondeurs des {link:wailing-caverns}Cavernes des lamentations{/link}.
• Elle organisa une toxine contre la {link:venture-company}KapitalRisk{/link} aux {link:stonetalon-mountains}Serres-Rocheuses{/link}, fabriquée par un collègue de {link:tarren-mill}Moulin-de-Tarren{/link}.]=],
		},
	},
	mentions = {
		{ text = "L'apothicaire Zamah" },
		{ text = "Fleur de serpent" },
		{ text = "Voyage vers {link:tarren-mill}Moulin-de-Tarren{/link}" },
		{ text = "L'aéroport des machines volantes" },
	},
	bonds = {
		{ id = "magatha-grimtotem", name = "Magatha Grimtotem", note = "lui envoie des chercheurs" },
	},
})

Translate("frFR", "melor-stonehoof", {
	title = "Melor Stonehoof",
	subtitle = "Maître de la chasse",
	found = "Cime des chasseurs",
	hint = [=[Cherchez le grand chasseur qui organise les chasses les plus dures depuis la Cime des chasseurs.]=],
	allegiance = "Taurens · Cime des chasseurs",
	aliases = { "Melor" },
	sections = {
		{
			title = "Résumé",
			text = [=[Melor Stonehoof est le grand chasseur de la {link:hunter-rise}Cime des chasseurs{/link}. Il montre aux jeunes la voie du chasseur, et il envoie ceux qui ont fait leurs preuves en des chasses qui ne visent ni la nourriture, ni l'honneur, ni l'enseignement. Ce sont des chasses contre des bêtes qui vivent hors de la bénédiction de la Terre-mère : des tyrans qui répandent la peur parmi les créatures plus paisibles.]=],
		},
		{
			title = "Importance",
			text = [=[Melor garde la chasse juste. Pour lui, le but de la poursuite compte autant que la mise à mort.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il envoie les jeunes chasseurs dans les {link:the-barrens}Tarides{/link} pour apprendre de leurs bêtes.
• Il organise des chasses contre la hyène {link:steelsnap}Steelsnap{/link} et d'autres bêtes tyranniques.
• Sa parole atteint les chasseurs confirmés jusque dans les Tarides, portée par des messagers qui vont à leur recherche.]=],
		},
	},
	mentions = {
		{ text = "La voie du chasseur" },
		{ text = "{link:sergra-darkthorn}Sergra Darkthorn{/link}" },
		{ text = "Melor envoie un message" },
		{ text = "{link:steelsnap}Steelsnap{/link}" },
		{ text = "Frostmaw" },
		{ text = "{link:deadmire}Deadmire{/link}" },
	},
	bonds = {
		{ id = "skorn-whitecloud", name = "Skorn Whitecloud", note = "lui envoie de jeunes chasseurs" },
	},
})

Translate("frFR", "eyahn-eagletalon", {
	title = "Eyahn Eagletalon",
	subtitle = "Artisan des coiffes",
	found = "La cime inférieure de Thunder Bluff",
	hint = [=[Trouvez le tauren qui confectionne une coiffe de cérémonie sur la cime inférieure.]=],
	allegiance = "Taurens",
	aliases = { "Eyahn" },
	sections = {
		{
			title = "Résumé",
			text = [=[Eyahn Eagletalon confectionne une coiffe de cérémonie. Le frère d'Eyahn se présentera bientôt devant le grand chef, et fabriquer sa coiffe est un honneur. Les lanières de cuir sont presque tannées, mais le temps manque pour rassembler aussi les plumes : six azur et six bronze, de la taille qu'on ne trouve que sur les harpies au nord et au nord-ouest de la cité. Eyahn demande aux voyageurs de passage de chasser les harpies à sa place.]=],
		},
		{
			title = "Importance",
			text = [=[Eyahn maintient vivante l'une des petites coutumes de {link:thunder-bluff}Thunder Bluff{/link} : nul ne se présente devant {link:cairne-bloodhoof}Cairne{/link} sans parure.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Confectionne une coiffe pour un frère qui se présentera bientôt devant le grand chef.
• Tanne ses lanières de cuir pendant que d'autres rassemblent les plumes.]=],
		},
	},
	mentions = {
		{ text = "Préparatifs pour la cérémonie" },
	},
	bonds = {
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "le chef devant qui le frère se présentera" },
	},
})

Translate("frFR", "eylah-sunhorn", {
	title = "Eylah Sunhorn",
	subtitle = "Prêtre du soleil d'An'she",
	found = "La cime inférieure de Thunder Bluff",
	hint = [=[Cherchez le prêtre du soleil qui maintient la vieille tradition de l'encens.]=],
	allegiance = "Prêtres du soleil d'An'she · Taurens",
	aliases = { "Eylah" },
	sections = {
		{
			title = "Résumé",
			text = [=[Eylah Sunhorn est un prêtre d'An'she, le soleil, que les taurens honorent comme l'un des yeux de la Terre-mère. Eylah accueille les voyageurs avec la bénédiction d'An'she et maintient une vieille coutume des taurens : disperser de l'encens aux vents. L'encens est fait d'herbes, de cèdre, de fil de tendon et de silex de cérémonie, et on le jette depuis la falaise sud de la {link:hunter-rise}Cime des chasseurs{/link}.]=],
		},
		{
			title = "Importance",
			text = [=[Eylah est l'un des prêtres du soleil qui se sont fait connaître à {link:thunder-bluff}Thunder Bluff{/link} en ces jours.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Demande aux voyageurs d'honorer la tradition de l'encens.
• Les envoie chez l'herboriste, chez les fournisseurs des enchanteurs et des travailleurs du cuir, et chez le fournisseur du cuisinier de la cité pour en réunir les ingrédients.]=],
		},
	},
	mentions = {
		{ text = "Traditions des Pitons" },
	},
})

Translate("frFR", "grimtotem-clan", {
	title = "Clan Totem sinistre",
	aliases = { "clan Totem sinistre", "tribu Totem sinistre", "les Totem sinistre" },
	sections = {
		{
			title = "Résumé",
			text = [=[Les Totem sinistre sont un clan {link:tauren}tauren{/link} différent des autres. Là où la plupart des taurens recherchent l'harmonie avec la terre, les Totem sinistre cherchent à la maîtriser. Ils croient que les races inférieures devraient être chassées de {link:kalimdor}Kalimdor{/link} et que les taurens devraient reprendre les terres de leurs ancêtres. Leur matriarche est {link:magatha-grimtotem}Magatha{/link}, la doyenne, et leurs guerriers la suivent.]=],
		},
		{
			title = "Le clan et la cité",
			text = [=[{link:magatha-grimtotem}Magatha{/link} vit sur la {link:elder-rise}Cime des Anciens{/link} à {link:thunder-bluff}Thunder Bluff{/link}, gardée par des guerriers de son clan, et les Totem sinistre y jouissent des droits de tout {link:tauren}tauren{/link}. On dit que {link:cairne-bloodhoof}Cairne{/link} lui accorda une place si proche de lui dans l'esprit d'un vieux dicton : garde tes amis près de toi, et tes ennemis plus près encore. Dans les terres sauvages, le clan est une autre affaire.]=],
		},
		{
			title = "Dans les terres sauvages",
			text = [=[• {b}{link:thousand-needles}Mille pointes{/link}.{/b} Les Totem sinistre tiennent la {link:darkcloud-pinnacle}Cime de Noir-nuage{/link}, où ils enterrent leurs morts près d'un feu sacré. Les taurens du {link:freewind-post}Poste de Librevent{/link} les surveillent de près. Des agents d'origine inconnue ont été vus leur rendre visite, et un paria du clan, {link:arnak-grimtotem}Arnak{/link}, est recherché pour meurtre et enlèvement.
• {b}{link:stonetalon-mountains}Les Serres-Rocheuses{/link}.{/b} Des pillards Totem sinistre s'abattirent sur un village {link:tauren}tauren{/link} près des montagnes et tuèrent presque tous ses habitants.
• {b}Le {link:earthen-ring}Cercle terrestre{/link}.{/b} Tous les Totem sinistre ne suivent pas la voie du clan. En ces jours, un chaman nommé Yorn Grimtotem sert avec le Cercle terrestre en {link:mulgore}Mulgore{/link}.]=],
		},
	},
})
